trait Prompter {
    fn say(&mut self, text: &str);
    fn ask_feedback(&mut self) -> Option<String> {
        None
    }
}

struct Quiet;

impl Prompter for Quiet {
    fn say(&mut self, text: &str) {
        println!("{text}");
    }
}

fn main() {
    let mut p = Quiet;
    p.say("done");
    println!("{:?}", p.ask_feedback());
}
